<?php
declare(strict_types=1);requireRole('store-keeper');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='approved-dispatches';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT);$subject=filter_input(INPUT_POST,'subject_officer_id',FILTER_VALIDATE_INT);if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$id||!$subject)$errors[]='Select the approved request and named Subject Officer.';if(!$errors){try{$db->beginTransaction();$s=$db->prepare("SELECT * FROM goods_requests WHERE id=:id AND status='approved-awaiting-dispatch' FOR UPDATE");$s->execute(['id'=>$id]);$request=$s->fetch();if(!$request)throw new RuntimeException('This request is not approved for release.');$u=$db->prepare("SELECT id FROM users WHERE id=:id AND role='subject-officer' AND status='active'");$u->execute(['id'=>$subject]);if(!$u->fetchColumn())throw new RuntimeException('Select an active Subject Officer.');$stock=$db->prepare('SELECT quantity FROM inventory_items WHERE id=:item FOR UPDATE');$stock->execute(['item'=>$request['item_id']]);$available=(int)$stock->fetchColumn();if($available<(int)$request['quantity'])throw new RuntimeException("Insufficient central stock. Available: $available.");$db->prepare('UPDATE inventory_items SET quantity=quantity-:quantity WHERE id=:item')->execute(['quantity'=>$request['quantity'],'item'=>$request['item_id']]);$db->prepare("UPDATE goods_requests SET status='dispatched',dispatched_by=:keeper,dispatched_at=NOW(),released_to_subject_id=:subject,received_at=NOW() WHERE id=:id")->execute(['keeper'=>$_SESSION['user_id'],'subject'=>$subject,'id'=>$id]);$needs=$db->prepare("SELECT ar.id,LOWER(CONCAT(i.item_name,' ',i.variety,' ',c.name)) item_text FROM goods_request_aid_requests ga JOIN aid_requests ar ON ar.id=ga.aid_request_id JOIN inventory_items i ON i.id=ar.item_id JOIN item_categories c ON c.id=i.category_id WHERE ga.goods_request_id=:goods");$needs->execute(['goods'=>$id]);$insert=$db->prepare('INSERT INTO goods_fulfillments(goods_request_id,aid_request_id,subject_officer_id,lens_unit_identifier) VALUES(:goods,:aid,:subject,:unit)');$sequence=0;foreach($needs->fetchAll() as $need){$sequence++;$isLens=str_contains($need['item_text'],'contact')&&str_contains($need['item_text'],'lens');$unit=$isLens?'CL-GR'.str_pad((string)$id,4,'0',STR_PAD_LEFT).'-'.str_pad((string)$sequence,3,'0',STR_PAD_LEFT):null;$insert->execute(['goods'=>$id,'aid'=>$need['id'],'subject'=>$subject,'unit'=>$unit]);}$db->commit();logActivity('Dispatch','Released approved Goods Request to named Subject Officer','GR-'.str_pad((string)$id,4,'0',STR_PAD_LEFT),'dispatched');$_SESSION['flash_success']='Goods released to the selected Subject Officer.';unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=approved-dispatches');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to release goods.';}}}
try{$rows=$db->query("SELECT g.*,i.item_name,i.variety,i.quantity central_stock,ds.name division_name,d.name district_name,r.full_name requester_name,a.full_name approver_name FROM goods_requests g JOIN inventory_items i ON i.id=g.item_id JOIN ds_divisions ds ON ds.id=g.destination_ds_division_id JOIN districts d ON d.id=ds.district_id JOIN users r ON r.id=g.requested_by JOIN users a ON a.id=g.approved_by WHERE g.status='approved-awaiting-dispatch' ORDER BY g.approved_at,g.id")->fetchAll();$subjects=$db->query("SELECT id,full_name FROM users WHERE role='subject-officer' AND status='active' ORDER BY full_name")->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$rows=$subjects=[];$errors[]='Approved dispatches are unavailable.';}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Approved Dispatches | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/store-keeper-sidebar.php';?><div class="admin-shell"><header class="topbar"><h1>Approved Requests Ready for Dispatch</h1></header><main class="dashboard-content"><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors))?></div><?php endif;?><section class="dispatch-card"><div class="dispatch-card-header"><h2>Gate 2 Approved Requests</h2><small>Only Admin-approved Goods Requests appear here. Release is only to a named Subject Officer.</small></div><div class="dispatch-table-wrap"><table class="dispatch-table"><thead><tr><th>Request</th><th>Item</th><th>Qty</th><th>Stock</th><th>Destination</th><th>Approved By</th><th>Release To</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">No approved requests waiting.</td></tr><?php else:foreach($rows as $r):?><tr><td>GR-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' — '.$r['variety']:''))?></td><td><?=(int)$r['quantity']?></td><td><?=(int)$r['central_stock']?></td><td><?=htmlspecialchars($r['district_name'].' / '.$r['division_name'])?></td><td><?=htmlspecialchars($r['approver_name'])?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken())?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><select name="subject_officer_id" required><option value="">Select Subject Officer</option><?php foreach($subjects as $u):?><option value="<?=(int)$u['id']?>"><?=htmlspecialchars($u['full_name'])?></option><?php endforeach;?></select><button class="admin-primary-action">Release Goods</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
